package com.example.spendtracker.data.local.dao;

/** Range-safe materialized queries; local timezone changes do not invalidate UTC storage. */
public final class AnalyticsSql {
    private AnalyticsSql() { }
    public static final String TYPE_FACTS = "(SELECT type, bucket, total AS amount, transactionCount FROM analytics_daily_type WHERE day >= :start AND day <= :end - 86399999 UNION ALL SELECT COALESCE(CASE WHEN type = 'TRANSFER' OR LOWER(category) LIKE '%transfer%' THEN 'TRANSFER' WHEN category IS NULL THEN 'UNCLASSIFIED' ELSE type END, 'UNCLASSIFIED') AS type, '' AS bucket, amount, 1 AS transactionCount FROM transactions WHERE status = 'ACTIVE' AND date BETWEEN :start AND MIN(:end, (:start - ((:start % 86400000 + 86400000) % 86400000) + CASE WHEN ((:start % 86400000 + 86400000) % 86400000) = 0 THEN 0 ELSE 86400000 END) - 1) UNION ALL SELECT COALESCE(CASE WHEN type = 'TRANSFER' OR LOWER(category) LIKE '%transfer%' THEN 'TRANSFER' WHEN category IS NULL THEN 'UNCLASSIFIED' ELSE type END, 'UNCLASSIFIED') AS type, '' AS bucket, amount, 1 AS transactionCount FROM transactions WHERE status = 'ACTIVE' AND date BETWEEN MAX(:start, (:end - ((:end % 86400000 + 86400000) % 86400000)), (:start - ((:start % 86400000 + 86400000) % 86400000) + CASE WHEN ((:start % 86400000 + 86400000) % 86400000) = 0 THEN 0 ELSE 86400000 END)) AND :end AND ((:end % 86400000 + 86400000) % 86400000) != 86399999)";
    public static final String CATEGORY_FACTS = "(SELECT type, bucket, total AS amount, transactionCount FROM analytics_daily_category WHERE day >= :start AND day <= :end - 86399999 UNION ALL SELECT COALESCE(CASE WHEN type = 'TRANSFER' OR LOWER(category) LIKE '%transfer%' THEN 'TRANSFER' WHEN category IS NULL THEN 'UNCLASSIFIED' ELSE type END, 'UNCLASSIFIED') AS type, COALESCE(category,'') AS bucket, amount, 1 AS transactionCount FROM transactions WHERE status = 'ACTIVE' AND date BETWEEN :start AND MIN(:end, (:start - ((:start % 86400000 + 86400000) % 86400000) + CASE WHEN ((:start % 86400000 + 86400000) % 86400000) = 0 THEN 0 ELSE 86400000 END) - 1) UNION ALL SELECT COALESCE(CASE WHEN type = 'TRANSFER' OR LOWER(category) LIKE '%transfer%' THEN 'TRANSFER' WHEN category IS NULL THEN 'UNCLASSIFIED' ELSE type END, 'UNCLASSIFIED') AS type, COALESCE(category,'') AS bucket, amount, 1 AS transactionCount FROM transactions WHERE status = 'ACTIVE' AND date BETWEEN MAX(:start, (:end - ((:end % 86400000 + 86400000) % 86400000)), (:start - ((:start % 86400000 + 86400000) % 86400000) + CASE WHEN ((:start % 86400000 + 86400000) % 86400000) = 0 THEN 0 ELSE 86400000 END)) AND :end AND ((:end % 86400000 + 86400000) % 86400000) != 86399999)";
    public static final String MERCHANT_FACTS = "(SELECT type, bucket, total AS amount, transactionCount FROM analytics_daily_merchant WHERE day >= :start AND day <= :end - 86399999 UNION ALL SELECT COALESCE(CASE WHEN type = 'TRANSFER' OR LOWER(category) LIKE '%transfer%' THEN 'TRANSFER' WHEN category IS NULL THEN 'UNCLASSIFIED' ELSE type END, 'UNCLASSIFIED') AS type, COALESCE(receiverName,'') AS bucket, amount, 1 AS transactionCount FROM transactions WHERE status = 'ACTIVE' AND date BETWEEN :start AND MIN(:end, (:start - ((:start % 86400000 + 86400000) % 86400000) + CASE WHEN ((:start % 86400000 + 86400000) % 86400000) = 0 THEN 0 ELSE 86400000 END) - 1) UNION ALL SELECT COALESCE(CASE WHEN type = 'TRANSFER' OR LOWER(category) LIKE '%transfer%' THEN 'TRANSFER' WHEN category IS NULL THEN 'UNCLASSIFIED' ELSE type END, 'UNCLASSIFIED') AS type, COALESCE(receiverName,'') AS bucket, amount, 1 AS transactionCount FROM transactions WHERE status = 'ACTIVE' AND date BETWEEN MAX(:start, (:end - ((:end % 86400000 + 86400000) % 86400000)), (:start - ((:start % 86400000 + 86400000) % 86400000) + CASE WHEN ((:start % 86400000 + 86400000) % 86400000) = 0 THEN 0 ELSE 86400000 END)) AND :end AND ((:end % 86400000 + 86400000) % 86400000) != 86399999)";
    public static final String DASHBOARD_SUMMARY = "SELECT type, bucket AS category, SUM(amount) AS total, SUM(transactionCount) AS transactionCount, 0.0 AS accountTotal FROM " + CATEGORY_FACTS
            + " WHERE type IN ('INCOME','EXPENSE') GROUP BY type,bucket UNION ALL SELECT '__META' AS type, '' AS category, COALESCE(SUM(CASE WHEN type = 'TRANSFER' OR LOWER(category) LIKE '%transfer%' THEN CASE WHEN direction = 'CREDIT' OR (direction = 'UNKNOWN' AND type = 'INCOME') THEN amount ELSE -amount END ELSE 0 END),0.0) AS total, 0 AS transactionCount, COALESCE(SUM(CASE WHEN sourceType = 'Account' AND type != 'TRANSFER' AND LOWER(category) NOT LIKE '%transfer%' THEN amount ELSE 0 END),0.0) AS accountTotal FROM transactions WHERE status = 'ACTIVE' AND date BETWEEN :start AND :end";
}
